def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "communicate_request": And([
            self.person_at(self.coworker, self.coworker_desk),
            self.coworker_focused,
            Not(self.coworker_signal_given)
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
